  class Stamp {public string Source,Display;}
  public static string T(string text){if(string.IsNullOrEmpty(text)||Language=="zh-CN")return text;if(Language=="zh-TW"){var b=new StringBuilder(text.Length*3+16);return LCMapStringEx("zh-TW",0x04000000,text,text.Length,b,b.Capacity,IntPtr.Zero,IntPtr.Zero,IntPtr.Zero)>0?b.ToString():text;}string exact;if(en.TryGetValue(text,out exact))return exact;foreach(var row in en.OrderByDescending(x=>x.Key.Length))text=text.Replace(row.Key,row.Value);return text;}
  public static void Apply(Control control){if(!(control is TextBox)&&!(control is ListBox)&&!(control is MenuStrip)&&!Equals(control.Tag,"user")){
    var old=control.Tag as Stamp;string source=old!=null&&control.Text==old.Display?old.Source:control.Text;string translated=T(source);control.Tag=new Stamp{Source=source,Display=translated};if(control.Text!=translated)control.Text=translated;
   }foreach(Control c in control.Controls)Apply(c);}
  public static void Load(string root){string file=Path.Combine(root,"ui-language.txt");if(File.Exists(file)){string value=File.ReadAllText(file).Trim();if(new[]{"zh-CN","zh-TW","en-US"}.Contains(value))Language=value;}}
  public static void Save(string root,string language){if(!new[]{"zh-CN","zh-TW","en-US"}.Contains(language))throw new Exception("Invalid interface language");Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,"ui-language.txt"),language);Language=language;}
  public static DialogResult Show(IWin32Window owner,string text,string caption,MessageBoxButtons buttons,MessageBoxIcon icon,MessageBoxDefaultButton defaultButton=MessageBoxDefaultButton.Button1){return MessageBox.Show(owner,T(text),T(caption),buttons,icon,defaultButton);}
